export const boundary=[[-80.38,-4.99],[-80.17,-4.99],[-80.06,-4.83],[-80.14,-4.62],[-80.32,-4.66],[-80.40,-4.84],[-80.38,-4.99]];
export function inside(lat,lon){if(!Number.isFinite(lat)||!Number.isFinite(lon))return false;let c=false;for(let i=0,j=boundary.length-1;i<boundary.length;j=i++){let [x,y]=boundary[i],[xx,yy]=boundary[j];if(((y>lat)!=(yy>lat))&&(lon<(xx-x)*(lat-y)/(yy-y)+x))c=!c;}return c;}
export const locations=[{name:'Tambogrande · punto de referencia',lat:-4.926,lon:-80.344},{name:'Las Lomas · punto de referencia',lat:-4.653,lon:-80.241},{name:'Zona piloto central · punto exploratorio',lat:-4.80,lon:-80.25}];
export function search(q,farms=[]){const norm=s=>s.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();return [...locations,...farms.map(f=>({name:f.name,lat:f.lat,lon:f.lon}))].filter(p=>inside(p.lat,p.lon)&&norm(p.name).includes(norm(q)));}
export function demo(){return Array.from({length:365},(_,i)=>{let d=new Date(Date.UTC(2025,0,i+1));return {date:d.toISOString().slice(0,10),temp:+(29+4*Math.cos((i-45)/58)+Math.sin(i*1.7)*1.4).toFixed(2),rain:+(i<120&&i%5===0?8+6*Math.sin(i)**2:0).toFixed(2)};});}
export function evaluate(f){let water=Math.min(100,Math.max(0,(30-f.moisture)*4)+Math.min(40,f.days*2));let heat=Math.min(100,Math.max(0,(f.surface-32)*15))*(f.crop.startsWith('Mango')&&f.stage==='floración'?1:.5);let rain=Math.min(100,f.rain*2);let ivap=Math.round(.5*water+.3*heat+.2*rain);let status=Math.max(water,heat,rain)>=80||ivap>=70?'ALERTA CRÍTICA':Math.max(water,heat,rain)>=40||ivap>=35?'ADVERTENCIA':'NORMAL';return {water,heat,rain,ivap,status,compatibility:Math.round(Math.max(0,100-water*(['floración','cuajado','llenado de fruto'].includes(f.stage)?.5:.3)-heat*.25-rain*.15-(['arenoso','franco arenoso'].includes(f.soil)?10:0)))};}
export function rotations(f){return [['Leguminosa → descanso',5,1,2],['Maíz → leguminosa → descanso',10,3,3],['Yuca → descanso',14,2,2]].map(([name,months,water,income])=>{let reasons=[];if(!f.annual)reasons.push('Sin lote anual separado');if(water>f.water)reasons.push('Agua insuficiente');if(months>f.horizon)reasons.push('Excede horizonte');return {name,months,water,reasons,score:f.priority==='agua'?100-water*25:f.priority==='ciclo'?100-months*5:income*25};}).sort((a,b)=>Number(!b.reasons.length)-Number(!a.reasons.length)||b.score-a.score);}
export function metrics(rows){let errors=[];for(let i=1;i<rows.length;i++){if(rows[i].date>='2025-10-01'&&rows[i].temp!==null&&rows[i-1].temp!==null&&(Date.parse(rows[i].date)-Date.parse(rows[i-1].date))===86400000)errors.push(rows[i-1].temp-rows[i].temp);}return errors.length?{n:errors.length,mae:errors.reduce((a,b)=>a+Math.abs(b),0)/errors.length,rmse:Math.sqrt(errors.reduce((a,b)=>a+b*b,0)/errors.length)}:null;}
